"""In-memory fleet state, event log, and WebSocket broadcaster.

Single process, single source of truth. No DB — this is a hackathon spine.
"""

from __future__ import annotations

import asyncio
from collections import deque

from .models import (
    Counters,
    EventType,
    FleetSnapshot,
    Heartbeat,
    LiveEvent,
    NodeState,
    NodeView,
)

OFFLINE_AFTER_S = 10.0


class Node:
    def __init__(self, node_id: str, ts: float, fw_version: str = "v1") -> None:
        self.node_id = node_id
        self.state = NodeState.NORMAL
        self.last_seen = ts
        self.fw_version = fw_version
        self.label = node_id
        self.blocked = 0

    def view(self) -> NodeView:
        return NodeView(
            node_id=self.node_id,
            state=self.state,
            last_seen=self.last_seen,
            fw_version=self.fw_version,
            label=self.label,
            blocked=self.blocked,
        )


class Broadcaster:
    """Fan-out of LiveEvents to all connected WebSocket clients."""

    def __init__(self) -> None:
        self._queues: set[asyncio.Queue[LiveEvent]] = set()

    def subscribe(self) -> asyncio.Queue[LiveEvent]:
        q: asyncio.Queue[LiveEvent] = asyncio.Queue(maxsize=256)
        self._queues.add(q)
        return q

    def unsubscribe(self, q: asyncio.Queue[LiveEvent]) -> None:
        self._queues.discard(q)

    def publish(self, event: LiveEvent) -> None:
        for q in list(self._queues):
            try:
                q.put_nowait(event)
            except asyncio.QueueFull:
                # Slow client: drop oldest, keep the stream live.
                try:
                    q.get_nowait()
                    q.put_nowait(event)
                except (asyncio.QueueEmpty, asyncio.QueueFull):
                    pass


class AppState:
    def __init__(self) -> None:
        self.nodes: dict[str, Node] = {}
        self.events: deque[LiveEvent] = deque(maxlen=200)
        self.counters = Counters()
        self.broadcaster = Broadcaster()

    # --- ingest paths ----------------------------------------------------
    def apply_heartbeat(self, hb: Heartbeat) -> bool:
        """Update fleet from a heartbeat. Returns True if this is a new node."""
        is_new = hb.node_id not in self.nodes
        node = self.nodes.get(hb.node_id) or Node(hb.node_id, hb.timestamp)
        node.last_seen = hb.timestamp
        node.fw_version = hb.stats.fw_version
        node.blocked = hb.stats.blocked
        # A heartbeat's own state is advisory; orchestrator owns ALERT/UPDATING.
        if node.state in (NodeState.OFFLINE, NodeState.NORMAL):
            node.state = hb.state
        self.nodes[hb.node_id] = node
        self._recount()
        return is_new

    def set_node_state(self, node_id: str, state: NodeState) -> None:
        node = self.nodes.get(node_id)
        if node is not None:
            node.state = state
            self._recount()

    def mark_offline(self, now: float) -> list[str]:
        """Flip stale nodes to OFFLINE. Returns node_ids newly offline."""
        newly: list[str] = []
        for node in self.nodes.values():
            if (
                node.state is not NodeState.OFFLINE
                and now - node.last_seen > OFFLINE_AFTER_S
            ):
                node.state = NodeState.OFFLINE
                newly.append(node.node_id)
        if newly:
            self._recount()
        return newly

    # --- events ----------------------------------------------------------
    def emit(self, event: LiveEvent) -> None:
        # Counter side effects live here so mock and real paths agree.
        if event.type is EventType.ANOMALY_DETECTED:
            self.counters.threats_detected += 1
        elif event.type is EventType.DEPLOYED:
            self.counters.filters_deployed += 1
        elif event.type is EventType.FRAME_BLOCKED:
            n = int(event.payload.get("count", 1))
            self.counters.frames_blocked += n
            if event.node_id and event.node_id in self.nodes:
                self.nodes[event.node_id].blocked += n
        self.events.append(event)
        self.broadcaster.publish(event)

    def _recount(self) -> None:
        self.counters.active_nodes = sum(
            1 for n in self.nodes.values() if n.state is not NodeState.OFFLINE
        )

    def snapshot(self) -> FleetSnapshot:
        return FleetSnapshot(
            nodes=[n.view() for n in self.nodes.values()],
            counters=self.counters,
        )

/*
 * Independent oracle harness.
 *
 * Replays two labeled capture files through the agent-written filter and
 * scores it. This is the authoritative verification — the backend runs it
 * on human-prepared, held-out fixtures the agent never sees.
 *
 *   argv[1] = attack capture  (every frame SHOULD be blocked -> expect true)
 *   argv[2] = benign capture   (every frame should PASS       -> expect false)
 *
 * Fixture format: one frame per line as hex (e.g. "c000...").
 * Blank lines and lines starting with '#' are ignored.
 *
 * The agent's filter is dropped next to this file as filter.c and must define:
 *   bool block_frame(const uint8_t *f, size_t n);
 *
 * Output (machine-parseable, last line is authoritative):
 *   TPR=1.000 FPR=0.000 PASSED=8 TOTAL=8
 *   RESULT=PASS
 */
#include <ctype.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "filter.c"

#define MAX_LINE 8192
#define MAX_FRAME 4096

/* Parse one hex line into bytes. Returns frame length, or -1 to skip. */
static int parse_hex(const char *line, uint8_t *out, size_t cap) {
    size_t n = 0;
    int hi = -1;
    for (const char *p = line; *p; ++p) {
        char c = *p;
        if (c == '#') break;              /* inline comment */
        if (isspace((unsigned char)c)) continue;
        int v;
        if (c >= '0' && c <= '9') v = c - '0';
        else if (c >= 'a' && c <= 'f') v = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') v = c - 'A' + 10;
        else return -1;                   /* junk -> skip line */
        if (hi < 0) {
            hi = v;
        } else {
            if (n >= cap) return (int)n;
            out[n++] = (uint8_t)((hi << 4) | v);
            hi = -1;
        }
    }
    if (n == 0) return -1;                 /* blank/comment line */
    return (int)n;
}

/* Run the filter over a file. expect_block=true for attack, false for benign.
 * Increments *correct for each frame classified as expected, *total per frame. */
static int score_file(const char *path, bool expect_block, int *correct, int *total) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "oracle: cannot open %s\n", path);
        return -1;
    }
    char line[MAX_LINE];
    uint8_t frame[MAX_FRAME];
    while (fgets(line, sizeof line, fp)) {
        int len = parse_hex(line, frame, sizeof frame);
        if (len < 0) continue;
        bool blocked = block_frame(frame, (size_t)len);
        *total += 1;
        if (blocked == expect_block) *correct += 1;
    }
    fclose(fp);
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "usage: %s <attack.hex> <benign.hex>\n", argv[0]);
        return 2;
    }

    int tp = 0, attack_total = 0;   /* attack frames correctly blocked */
    int tn = 0, benign_total = 0;   /* benign frames correctly passed  */

    if (score_file(argv[1], true, &tp, &attack_total) < 0) return 2;
    if (score_file(argv[2], false, &tn, &benign_total) < 0) return 2;

    int fn = attack_total - tp;     /* attacks that slipped through */
    int fp = benign_total - tn;     /* legit frames wrongly blocked */

    double tpr = attack_total ? (double)tp / attack_total : 0.0;
    double fpr = benign_total ? (double)fp / benign_total : 0.0;

    int total = attack_total + benign_total;
    int passed = tp + tn;

    /* Pass = catches every attack AND blocks nothing legit. */
    bool ok = (fn == 0) && (fp == 0) && (attack_total > 0);

    printf("TPR=%.3f FPR=%.3f PASSED=%d TOTAL=%d\n", tpr, fpr, passed, total);
    printf("RESULT=%s\n", ok ? "PASS" : "FAIL");
    return ok ? 0 : 1;
}

/*
 * Sample filter — the shape the agent (Devin) is expected to emit.
 *
 * Blocks 802.11 management deauthentication / disassociation frames, the
 * payload of a deauth/disassoc flood. The first byte of an 802.11 frame is
 * the Frame Control field: bits [7:4] = subtype, bits [3:2] = type.
 *
 *   type 00 = management
 *   subtype 1100 (0xC) = deauthentication  -> FC = 0xC0
 *   subtype 1010 (0xA) = disassociation    -> FC = 0xA0
 *
 * Data (0x08) and beacon (0x80) frames pass untouched.
 */
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

bool block_frame(const uint8_t *f, size_t n) {
    if (n < 1) return false;
    uint8_t fc = f[0];
    uint8_t type = (fc >> 2) & 0x3;
    uint8_t subtype = (fc >> 4) & 0xF;
    if (type != 0x0) return false;                 /* only management frames */
    return subtype == 0xC || subtype == 0xA;       /* deauth or disassoc     */
}

