"""Fake 'Devin' agent — canned filters behind the real AgentIn->AgentOut contract.

Swapped for a real Devin/LLM call at integration (see ARCHITECTURE.md §5 step 2).
The orchestrator does not care which one it talks to.

To exercise the real fail->retry->pass loop, the first attempt over-blocks
(catches every management frame, so beacons get dropped -> FPR>0 -> oracle FAIL)
and the retry, once handed the failure log, narrows to deauth/disassoc only.
"""

from __future__ import annotations

from pathlib import Path

from .models import AgentIn, AgentOut

_GOOD_FILTER = (Path(__file__).resolve().parent.parent / "oracle/filters/deauth.c").read_text()

_OVERBROAD_FILTER = """\
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* First guess: block ALL management frames. Too aggressive — drops beacons. */
bool block_frame(const uint8_t *f, size_t n) {
    if (n < 1) return false;
    uint8_t type = (f[0] >> 2) & 0x3;
    return type == 0x0;
}
"""


def call_agent(payload: AgentIn) -> AgentOut:
    retrying = bool(payload.failure_log or payload.prev_filter)
    if retrying:
        return AgentOut(
            attack_class="deauth_flood",
            confidence=0.94,
            filter_c_code=_GOOD_FILTER,
            explanation=(
                "Narrowed to 802.11 mgmt subtypes 0xC (deauth) and 0xA (disassoc); "
                "beacons and data frames now pass."
            ),
        )
    return AgentOut(
        attack_class="deauth_flood",
        confidence=0.71,
        filter_c_code=_OVERBROAD_FILTER,
        explanation="Initial guess: high volume of management frames — block all mgmt.",
    )

"""The independent oracle passes a correct filter and fails broken ones."""

from pathlib import Path

from app.oracle import run_oracle

GOOD = (Path(__file__).resolve().parent.parent / "oracle/filters/deauth.c").read_text()

OVERBROAD = """\
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
bool block_frame(const uint8_t *f, size_t n) {
    if (n < 1) return false;
    return ((f[0] >> 2) & 0x3) == 0x0;  /* blocks all mgmt incl. beacons */
}
"""

WONT_COMPILE = "this is not C code {{{"


def test_good_filter_passes():
    out = run_oracle(GOOD)
    assert out.passed is True
    assert out.tpr == 1.0
    assert out.fpr == 0.0
    assert out.tests_passed == out.tests_total > 0


def test_overbroad_filter_fails_on_false_positives():
    out = run_oracle(OVERBROAD)
    assert out.passed is False
    assert out.fpr > 0.0  # beacons/probes wrongly blocked


def test_compile_error_is_a_failure_not_a_crash():
    out = run_oracle(WONT_COMPILE)
    assert out.passed is False
    assert "compile failed" in out.log

// Mirror of backend contracts (ARCHITECTURE.md §4). Keep in sync with
// backend/app/models.py — do not diverge without updating both sides.

export type NodeState = "NORMAL" | "ALERT" | "PROTECTED" | "UPDATING" | "OFFLINE";

export type EventType =
  | "NODE_UP"
  | "NODE_DOWN"
  | "ANOMALY_DETECTED"
  | "AGENT_ANALYZING"
  | "FILTER_GENERATED"
  | "VERIFYING"
  | "VERIFY_FAILED"
  | "VERIFY_PASSED"
  | "OTA_DEPLOYING"
  | "DEPLOYED"
  | "FRAME_BLOCKED";

export interface NodeView {
  node_id: string;
  state: NodeState;
  last_seen: number;
  fw_version: string;
  label: string;
  blocked: number;
}

export interface Counters {
  active_nodes: number;
  threats_detected: number;
  filters_deployed: number;
  frames_blocked: number;
}

export interface FleetSnapshot {
  nodes: NodeView[];
  counters: Counters;
}

export interface LiveEvent {
  type: EventType;
  node_id: string | null;
  ts: number;
  payload: Record<string, unknown>;
}

// The bootstrap frame the server sends first on /live.
export interface SnapshotMessage {
  type: "SNAPSHOT";
  payload: FleetSnapshot;
}

export type WsMessage = LiveEvent | SnapshotMessage;

// Pipeline stages for the loop animation.
export type Stage = "idle" | "trigger" | "agent" | "verify" | "ota" | "done";

export interface TimelineLine {
  id: number;
  ts: number;
  node_id: string | null;
  type: EventType;
  text: string;
  tone: "info" | "warn" | "ok" | "bad";
}

export interface DashState {
  nodes: Record<string, NodeView>;
  counters: Counters;
  timeline: TimelineLine[];
  stage: Stage;
  activeNode: string | null;
  activeAttack: string | null;
  seq: number;
}

// Pure reducer: folds WS messages into dashboard state. No React, no I/O —
// so it is unit-testable in isolation (see reducer.test.ts).

import type { DashState, LiveEvent, NodeState, TimelineLine, WsMessage } from "./types";

export const initialState: DashState = {
  nodes: {},
  counters: { active_nodes: 0, threats_detected: 0, filters_deployed: 0, frames_blocked: 0 },
  timeline: [],
  stage: "idle",
  activeNode: null,
  activeAttack: null,
  seq: 0,
};

const STAGE_BY_TYPE: Partial<Record<LiveEvent["type"], DashState["stage"]>> = {
  ANOMALY_DETECTED: "trigger",
  AGENT_ANALYZING: "agent",
  VERIFYING: "verify",
  OTA_DEPLOYING: "ota",
  DEPLOYED: "done",
};

function describe(e: LiveEvent): { text: string; tone: TimelineLine["tone"] } {
  const p = e.payload;
  const node = e.node_id ?? "—";
  switch (e.type) {
    case "NODE_UP":
      return { text: `${node} online`, tone: "info" };
    case "NODE_DOWN":
      return { text: `${node} went offline`, tone: "bad" };
    case "ANOMALY_DETECTED":
      return { text: `⚠ ${node} anomaly — ${p.count ?? "?"} frames in window`, tone: "warn" };
    case "AGENT_ANALYZING":
      return { text: `${node} agent analyzing (attempt ${p.attempt ?? 1})`, tone: "info" };
    case "FILTER_GENERATED":
      return { text: `${node} filter generated → ${p.attack_class ?? "?"}`, tone: "info" };
    case "VERIFYING":
      return { text: `${node} verifying filter (replay test)`, tone: "info" };
    case "VERIFY_FAILED":
      return { text: `${node} verify FAILED ${p.tests ?? ""} (fpr=${p.fpr ?? "?"})`, tone: "bad" };
    case "VERIFY_PASSED":
      return { text: `${node} verify PASSED ${p.tests ?? ""} ✓`, tone: "ok" };
    case "OTA_DEPLOYING":
      return { text: `${node} deploying filter OTA…`, tone: "info" };
    case "DEPLOYED":
      return { text: `${node} PROTECTED — ${p.attack_class ?? "filter"} deployed ✓`, tone: "ok" };
    case "FRAME_BLOCKED":
      return { text: `${node} blocked ${p.count ?? 1} attack frames`, tone: "ok" };
    default:
      return { text: e.type, tone: "info" };
  }
}

function setNodeState(state: DashState, nodeId: string | null, ns: NodeState): DashState["nodes"] {
  if (!nodeId || !state.nodes[nodeId]) return state.nodes;
  return { ...state.nodes, [nodeId]: { ...state.nodes[nodeId], state: ns } };
}

export function reduce(state: DashState, msg: WsMessage): DashState {
  if (msg.type === "SNAPSHOT") {
    const nodes: DashState["nodes"] = {};
    for (const n of msg.payload.nodes) nodes[n.node_id] = n;
    return { ...state, nodes, counters: msg.payload.counters };
  }

  const e = msg;
  let nodes = state.nodes;
  const counters = { ...state.counters };
  let activeNode = state.activeNode;
  let activeAttack = state.activeAttack;

  switch (e.type) {
    case "NODE_UP":
      if (e.node_id && !nodes[e.node_id]) {
        nodes = {
          ...nodes,
          [e.node_id]: {
            node_id: e.node_id,
            state: "NORMAL",
            last_seen: e.ts,
            fw_version: "v1",
            label: e.node_id,
            blocked: 0,
          },
        };
      }
      break;
    case "NODE_DOWN":
      nodes = setNodeState(state, e.node_id, "OFFLINE");
      break;
    case "ANOMALY_DETECTED":
      nodes = setNodeState(state, e.node_id, "ALERT");
      counters.threats_detected += 1;
      activeNode = e.node_id;
      break;
    case "FILTER_GENERATED":
      activeAttack = (e.payload.attack_class as string) ?? activeAttack;
      break;
    case "OTA_DEPLOYING":
      nodes = setNodeState(state, e.node_id, "UPDATING");
      break;
    case "DEPLOYED":
      nodes = setNodeState(state, e.node_id, "PROTECTED");
      counters.filters_deployed += 1;
      break;
    case "FRAME_BLOCKED": {
      const c = Number(e.payload.count ?? 1);
      counters.frames_blocked += c;
      if (e.node_id && nodes[e.node_id]) {
        nodes = {
          ...nodes,
          [e.node_id]: { ...nodes[e.node_id], blocked: nodes[e.node_id].blocked + c },
        };
      }
      break;
    }
    default:
      break;
  }

  counters.active_nodes = Object.values(nodes).filter((n) => n.state !== "OFFLINE").length;

  const stage = STAGE_BY_TYPE[e.type] ?? state.stage;
  const { text, tone } = describe(e);
  const line: TimelineLine = { id: state.seq, ts: e.ts, node_id: e.node_id, type: e.type, text, tone };
  const timeline = [line, ...state.timeline].slice(0, 60);

  return { ...state, nodes, counters, timeline, stage, activeNode, activeAttack, seq: state.seq + 1 };
}

import { describe, expect, it } from "vitest";

import { initialState, reduce } from "./reducer";
import type { LiveEvent, SnapshotMessage } from "./types";

function ev(type: LiveEvent["type"], node_id: string | null, payload: Record<string, unknown> = {}): LiveEvent {
  return { type, node_id, ts: 1, payload };
}

const snapshot: SnapshotMessage = {
  type: "SNAPSHOT",
  payload: {
    nodes: [
      { node_id: "esp-01", state: "NORMAL", last_seen: 0, fw_version: "v1", label: "esp-01", blocked: 0 },
    ],
    counters: { active_nodes: 1, threats_detected: 0, filters_deployed: 0, frames_blocked: 0 },
  },
};

describe("reducer", () => {
  it("folds the full loop into node state + counters", () => {
    let s = reduce(initialState, snapshot);
    s = reduce(s, ev("ANOMALY_DETECTED", "esp-01", { count: 200 }));
    expect(s.nodes["esp-01"].state).toBe("ALERT");
    expect(s.counters.threats_detected).toBe(1);

    s = reduce(s, ev("OTA_DEPLOYING", "esp-01"));
    expect(s.nodes["esp-01"].state).toBe("UPDATING");

    s = reduce(s, ev("DEPLOYED", "esp-01", { attack_class: "deauth_flood" }));
    expect(s.nodes["esp-01"].state).toBe("PROTECTED");
    expect(s.counters.filters_deployed).toBe(1);
    expect(s.stage).toBe("done");

    s = reduce(s, ev("FRAME_BLOCKED", "esp-01", { count: 42 }));
    expect(s.counters.frames_blocked).toBe(42);
    expect(s.nodes["esp-01"].blocked).toBe(42);
  });

  it("greys a node on NODE_DOWN and drops active count", () => {
    let s = reduce(initialState, snapshot);
    expect(s.counters.active_nodes).toBe(1);
    s = reduce(s, ev("NODE_DOWN", "esp-01"));
    expect(s.nodes["esp-01"].state).toBe("OFFLINE");
    expect(s.counters.active_nodes).toBe(0);
  });
});

import { useEffect, useReducer, useState } from "react";

import { initialState, reduce } from "./reducer";
import type { WsMessage } from "./types";

const WS_URL = import.meta.env.VITE_WS_URL ?? "ws://localhost:8000/live";

export function useLive() {
  const [state, dispatch] = useReducer(reduce, initialState);
  const [connected, setConnected] = useState(false);

  useEffect(() => {
    let ws: WebSocket;
    let retry: ReturnType<typeof setTimeout>;
    let closed = false;

    const connect = () => {
      ws = new WebSocket(WS_URL);
      ws.onopen = () => setConnected(true);
      ws.onclose = () => {
        setConnected(false);
        if (!closed) retry = setTimeout(connect, 1000);
      };
      ws.onmessage = (msg) => {
        try {
          dispatch(JSON.parse(msg.data) as WsMessage);
        } catch {
          // ignore malformed frames
        }
      };
    };
    connect();

    return () => {
      closed = true;
      clearTimeout(retry);
      ws?.close();
    };
  }, []);

  return { state, connected };
}

import "./App.css";

import { useLive } from "./useLive";
import type { NodeView, Stage } from "./types";

const PIPELINE: { key: Stage; label: string }[] = [
  { key: "trigger", label: "① Anomaly" },
  { key: "agent", label: "② Agent writes filter" },
  { key: "verify", label: "③ Oracle verifies" },
  { key: "ota", label: "④ OTA deploy" },
];

const STAGE_ORDER: Stage[] = ["idle", "trigger", "agent", "verify", "ota", "done"];

function StatTile({ label, value, accent }: { label: string; value: number; accent?: string }) {
  return (
    <div className="tile" style={accent ? { borderColor: accent } : undefined}>
      <div className="tile-value" style={accent ? { color: accent } : undefined}>
        {value.toLocaleString()}
      </div>
      <div className="tile-label">{label}</div>
    </div>
  );
}

function NodeTile({ node }: { node: NodeView }) {
  return (
    <div className={`node node-${node.state.toLowerCase()}`}>
      <div className="node-id">{node.label}</div>
      <div className="node-state">{node.state}</div>
      <div className="node-meta">
        {node.fw_version} · {node.blocked.toLocaleString()} blocked
      </div>
    </div>
  );
}

export default function App() {
  const { state, connected } = useLive();
  const nodes = Object.values(state.nodes).sort((a, b) => a.node_id.localeCompare(b.node_id));
  const activeIdx = STAGE_ORDER.indexOf(state.stage);

  return (
    <div className="app">
      <header className="header">
        <h1>
          <span className="shield">🛡</span> Autonomous Anomaly Defense
        </h1>
        <div className={`conn ${connected ? "on" : "off"}`}>
          {connected ? "LIVE" : "reconnecting…"}
        </div>
      </header>

      <section className="counters">
        <StatTile label="Active nodes" value={state.counters.active_nodes} />
        <StatTile label="Threats detected" value={state.counters.threats_detected} accent="#e0a53f" />
        <StatTile label="Filters deployed" value={state.counters.filters_deployed} accent="#4ad98a" />
        <StatTile label="Frames blocked" value={state.counters.frames_blocked} accent="#d94a4a" />
      </section>

      <section className="main">
        <div className="panel grid-panel">
          <h2>Fleet</h2>
          <div className="node-grid">
            {nodes.length === 0 && <div className="empty">waiting for nodes…</div>}
            {nodes.map((n) => (
              <NodeTile key={n.node_id} node={n} />
            ))}
          </div>
        </div>

        <div className="panel pipe-panel">
          <h2>Defense loop {state.activeAttack ? `· ${state.activeAttack}` : ""}</h2>
          <div className="pipeline">
            {PIPELINE.map((step) => {
              const idx = STAGE_ORDER.indexOf(step.key);
              const cls = idx < activeIdx ? "past" : idx === activeIdx ? "active" : "future";
              return (
                <div key={step.key} className={`pstep ${cls}`}>
                  <div className="pdot" />
                  <div className="plabel">{step.label}</div>
                </div>
              );
            })}
          </div>
          <div className="pipe-note">
            No human in the loop — deploy only after the oracle passes on held-out captures.
          </div>
        </div>
      </section>

      <section className="panel timeline-panel">
        <h2>Live timeline</h2>
        <ul className="timeline">
          {state.timeline.map((l) => (
            <li key={l.id} className={`line ${l.tone}`}>
              {l.text}
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}

