"""Thin Langfuse facade — traces the Devin loop for the pitch/debug.

Degrades to a no-op when Langfuse is not configured or the SDK is missing, so
nothing here can break the request path. One trace per anomaly loop; spans for
each agent session and oracle verdict nest under it.
"""

from __future__ import annotations

import contextlib
from collections.abc import Iterator
from typing import Any, Protocol

from .config import settings


class Span(Protocol):
    def update(self, **kwargs: Any) -> None: ...
    def end(self, **kwargs: Any) -> None: ...


class _NoopSpan:
    def update(self, **kwargs: Any) -> None:  # noqa: D401
        return None

    def end(self, **kwargs: Any) -> None:
        return None


class Trace(Protocol):
    def span(self, **kwargs: Any) -> Span: ...


class _NoopTrace:
    def span(self, **kwargs: Any) -> Span:
        return _NoopSpan()


_client: Any | None = None


def _get_client() -> Any | None:
    global _client
    if not settings.langfuse_enabled:
        return None
    if _client is None:
        try:
            from langfuse import Langfuse

            _client = Langfuse(
                public_key=settings.langfuse_public_key,
                secret_key=settings.langfuse_secret_key,
                host=settings.langfuse_host,
            )
        except Exception:  # noqa: BLE001 - tracing must never break the app
            _client = None
    return _client


def start_trace(name: str, **kwargs: Any) -> Trace:
    client = _get_client()
    if client is None:
        return _NoopTrace()
    try:
        return client.trace(name=name, **kwargs)
    except Exception:  # noqa: BLE001
        return _NoopTrace()


@contextlib.contextmanager
def span(trace: Trace, name: str, **kwargs: Any) -> Iterator[Span]:
    """Open a span on `trace`; always yields something with update()/end()."""
    try:
        s: Span = trace.span(name=name, **kwargs)
    except Exception:  # noqa: BLE001
        s = _NoopSpan()
    try:
        yield s
    finally:
        with contextlib.suppress(Exception):
            s.end()


def flush() -> None:
    client = _get_client()
    if client is not None:
        with contextlib.suppress(Exception):
            client.flush()

"""Thin typed client for the Devin external API (v1).

Endpoints (base https://api.devin.ai/v1, Bearer auth):
  POST /sessions                 {prompt, structured_output?} -> {session_id, url}
  GET  /session/{session_id}     -> {status_enum, structured_output, ...}
  POST /session/{session_id}/message  {message}

A custom httpx transport can be injected for tests and offline mock runs.
"""

from __future__ import annotations

from typing import Any

import httpx
from pydantic import BaseModel, Field

from .config import settings

# status_enum values that mean "done, stop polling".
TERMINAL_STATUSES = {"finished", "blocked", "expired"}


class DevinSession(BaseModel):
    session_id: str
    url: str | None = None
    status_enum: str | None = None
    # Devin returns this as an object (or a JSON string); keep it loose here and
    # parse in the agent.
    structured_output: Any = None
    title: str | None = Field(default=None)

    @property
    def is_terminal(self) -> bool:
        return self.status_enum in TERMINAL_STATUSES


class DevinClient:
    def __init__(
        self,
        api_key: str | None = None,
        base_url: str | None = None,
        transport: httpx.BaseTransport | None = None,
        timeout: float = 30.0,
    ) -> None:
        self.api_key = api_key if api_key is not None else settings.devin_api_key
        self.base_url = (base_url or settings.devin_base_url).rstrip("/")
        self._client = httpx.Client(
            base_url=self.base_url,
            headers={"Authorization": f"Bearer {self.api_key}"},
            timeout=timeout,
            transport=transport,
        )

    def create_session(self, prompt: str, structured_output: str | None = None) -> DevinSession:
        body: dict[str, Any] = {"prompt": prompt}
        if structured_output:
            body["structured_output"] = structured_output
        resp = self._client.post("/sessions", json=body)
        resp.raise_for_status()
        return DevinSession.model_validate(resp.json())

    def get_session(self, session_id: str) -> DevinSession:
        resp = self._client.get(f"/session/{session_id}")
        resp.raise_for_status()
        data = resp.json()
        data.setdefault("session_id", session_id)
        return DevinSession.model_validate(data)

    def send_message(self, session_id: str, message: str) -> None:
        resp = self._client.post(f"/session/{session_id}/message", json={"message": message})
        resp.raise_for_status()

    def close(self) -> None:
        self._client.close()

"""DevinAgent — drives a real Devin session to write the C filter.

Behind the frozen AgentIn -> AgentOut contract, so it drops into the orchestrator
as a one-liner later. Standalone-runnable from the CLI (see __main__) with a
--mock mode that needs no API key or network.
"""

from __future__ import annotations

import argparse
import json
import re
import time
from pathlib import Path
from typing import Any

import httpx

from .config import settings
from .devin_client import DevinClient
from .models import AgentIn, AgentOut, AnomalyStats
from .prompts import STRUCTURED_OUTPUT_SPEC, build_devin_prompt
from . import tracing

_FILTERS_DIR = Path(__file__).resolve().parent.parent / "oracle/filters"
_FIXTURES = Path(__file__).resolve().parent.parent / "oracle/fixtures"


class DevinAgentError(RuntimeError):
    """Devin failed to produce a usable filter (timeout / no key / bad output)."""


def _extract_json(raw: Any) -> dict[str, Any]:
    """structured_output may be a dict already, or a (possibly fenced) JSON string."""
    if isinstance(raw, dict):
        return raw
    if isinstance(raw, str):
        text = raw.strip()
        fenced = re.search(r"```(?:json)?\s*(\{.*\})\s*```", text, re.DOTALL)
        if fenced:
            text = fenced.group(1)
        try:
            parsed = json.loads(text)
        except json.JSONDecodeError as exc:
            raise DevinAgentError(f"structured_output is not valid JSON: {exc}") from exc
        if isinstance(parsed, dict):
            return parsed
    raise DevinAgentError(f"unexpected structured_output type: {type(raw).__name__}")


def _to_agent_out(data: dict[str, Any]) -> AgentOut:
    if "filter_c_code" not in data:
        raise DevinAgentError("structured_output missing 'filter_c_code'")
    return AgentOut(
        attack_class=str(data.get("attack_class", "unknown")),
        confidence=float(data.get("confidence", 0.0)),
        filter_c_code=str(data["filter_c_code"]),
        explanation=str(data.get("explanation", "")),
    )


class DevinAgent:
    def __init__(self, client: DevinClient | None = None) -> None:
        if client is None and not settings.devin_api_key:
            raise DevinAgentError("DEVIN_API_KEY is not set (use --mock or set .env)")
        self.client = client or DevinClient()
        self._session_id: str | None = None

    def call(self, payload: AgentIn) -> AgentOut:
        trace = tracing.start_trace("devin.agent", input={"stats": payload.anomaly_stats.model_dump()})

        # Retry path: reuse the open session with a follow-up message.
        if payload.failure_log and self._session_id:
            with tracing.span(trace, "devin.retry_message", input={"log": payload.failure_log[:2000]}):
                self.client.send_message(
                    self._session_id,
                    "Independent verification failed. Fix filter.c.\n\n"
                    f"Failure log:\n{payload.failure_log}",
                )
        else:
            prompt = build_devin_prompt(payload)
            with tracing.span(trace, "devin.create_session", input={"prompt_chars": len(prompt)}) as sp:
                session = self.client.create_session(prompt, structured_output=STRUCTURED_OUTPUT_SPEC)
                self._session_id = session.session_id
                sp.update(output={"session_id": session.session_id, "url": session.url})

        session = self._poll(trace)
        data = _extract_json(session.structured_output)
        out = _to_agent_out(data)
        trace_out = {"attack_class": out.attack_class, "confidence": out.confidence}
        with tracing.span(trace, "devin.result", output=trace_out):
            pass
        return out

    def _poll(self, trace: tracing.Trace) -> Any:
        assert self._session_id is not None
        deadline = time.monotonic() + settings.devin_timeout_s
        polls = 0
        while True:
            session = self.client.get_session(self._session_id)
            polls += 1
            if session.is_terminal or session.structured_output is not None:
                with tracing.span(trace, "devin.poll_done", output={"polls": polls, "status": session.status_enum}):
                    pass
                if session.structured_output is None:
                    raise DevinAgentError(
                        f"session {self._session_id} ended ({session.status_enum}) with no structured_output"
                    )
                return session
            if time.monotonic() > deadline:
                raise DevinAgentError(
                    f"Devin session {self._session_id} timed out after {settings.devin_timeout_s}s"
                )
            time.sleep(settings.devin_poll_interval_s)


# --- offline mock client (no key / no network) ---------------------------
def build_mock_client(filter_code: str | None = None) -> DevinClient:
    """A DevinClient wired to a scripted transport returning a canned filter."""
    code = filter_code if filter_code is not None else (_FILTERS_DIR / "deauth.c").read_text()
    structured = json.dumps(
        {
            "attack_class": "deauth_flood",
            "confidence": 0.95,
            "filter_c_code": code,
            "explanation": "Blocks 802.11 mgmt deauth/disassoc frames; data/beacons pass.",
        }
    )
    state = {"gets": 0}

    def handler(request: httpx.Request) -> httpx.Response:
        if request.method == "POST" and request.url.path.endswith("/sessions"):
            return httpx.Response(200, json={"session_id": "mock-session", "url": "https://app.devin.ai/mock"})
        if request.method == "POST" and request.url.path.endswith("/message"):
            return httpx.Response(200, json={"ok": True})
        if request.method == "GET":
            state["gets"] += 1
            # First poll "working", then done — mimics real latency shape.
            if state["gets"] < 2:
                return httpx.Response(200, json={"status_enum": "working", "structured_output": None})
            return httpx.Response(200, json={"status_enum": "finished", "structured_output": structured})
        return httpx.Response(404, json={"error": "unmapped"})

    return DevinClient(api_key="mock", transport=httpx.MockTransport(handler))


# --- standalone CLI -------------------------------------------------------
def _load_frames(args: argparse.Namespace) -> list[str]:
    if args.frames_file:
        lines = Path(args.frames_file).read_text().splitlines()
        return [ln.strip() for ln in lines if ln.strip() and not ln.startswith("#")]
    # default --fixtures: the sample attack capture
    lines = (_FIXTURES / "attack.hex").read_text().splitlines()
    return [ln.strip() for ln in lines if ln.strip() and not ln.startswith("#")]


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Standalone Devin anomaly-defense agent")
    parser.add_argument("--frames-file", help="hex frames, one per line (default: sample fixtures)")
    parser.add_argument("--fixtures", action="store_true", help="use bundled sample attack frames")
    parser.add_argument("--mock", action="store_true", help="offline: no API key / network")
    parser.add_argument("--no-verify", dest="verify", action="store_false", help="skip oracle verify")
    parser.set_defaults(verify=True)
    args = parser.parse_args(argv)

    frames = _load_frames(args)
    payload = AgentIn(
        frame_hex=frames,
        anomaly_stats=AnomalyStats(frame_type="mgmt", subtype=12, count_in_window=len(frames)),
    )

    agent = DevinAgent(client=build_mock_client() if args.mock else None)
    try:
        out = agent.call(payload)
    except DevinAgentError as exc:
        print(f"❌ Devin agent failed: {exc}")
        return 1

    print(f"attack_class : {out.attack_class}")
    print(f"confidence   : {out.confidence}")
    print(f"explanation  : {out.explanation}")
    print("---- filter.c ----")
    print(out.filter_c_code)
    print("------------------")

    if args.verify:
        from .oracle import run_oracle

        verdict = run_oracle(out.filter_c_code)
        mark = "✅" if verdict.passed else "❌"
        print(f"{mark} oracle: passed={verdict.passed} tpr={verdict.tpr} fpr={verdict.fpr} "
              f"({verdict.tests_passed}/{verdict.tests_total})")

    if settings.langfuse_enabled:
        print(f"langfuse: trace sent to {settings.langfuse_host}")
    tracing.flush()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

